/**
 * Passwords, including the 112,000 that arrive from the Laravel sites.
 *
 * Laravel writes bcrypt hashes with the `$2y$` prefix. bcryptjs verifies them
 * as they are — tested against hashes generated by the sites' own PHP, not
 * assumed — so a migrated subscriber signs in with the password they already
 * have and nobody is forced to reset anything.
 *
 * New hashes are written as `$2a$` at cost 12 — bcryptjs's own output, and
 * checked against the sites' PHP 7.3: `password_verify` accepts it. So a
 * password changed here still works if a brand were ever rolled back to its
 * old site, which is the point of keeping the two readable to each other.
 */

import bcrypt from "bcryptjs";

/** Laravel's default is 10; raising it costs login latency on every request. */
export const COST = 12;

export async function hashPassword(plain: string): Promise<string> {
  return bcrypt.hash(plain, COST);
}

export async function verifyPassword(plain: string, hash: string | null): Promise<boolean> {
  if (!hash) {
    return false;
  }

  try {
    return await bcrypt.compare(plain, hash);
  } catch {
    // A truncated or otherwise unreadable hash is a failed sign-in, never a
    // 500 that tells the caller something about the account.
    return false;
  }
}

/** True for a hash the sites wrote, which is worth re-hashing on next sign-in. */
export function isLegacyHash(hash: string | null): boolean {
  if (!hash) {
    return false;
  }

  const cost = /^\$2[aby]\$(\d{2})\$/.exec(hash);

  return hash.startsWith("$2y$") || (cost !== null && Number(cost[1]) < COST);
}
